def resolve(path, cwd, links):
    """
    Resolve a path to its canonical absolute path, following symlinks.

    Args:
        path: The path to resolve (absolute or relative to cwd)
        cwd: The current working directory (canonical absolute path)
        links: Dict mapping canonical absolute paths to symlink targets

    Returns:
        The canonical absolute path, or None on error
    """
    # Track symlinks followed to detect cycles
    link_count = 0
    MAX_LINKS = 8

    # Start with absolute path
    if path.startswith('/'):
        current = '/'
        remaining = path[1:]
    else:
        current = cwd
        remaining = path

    # Split remaining path into components
    while True:
        # Split off the next component
        if not remaining:
            components = []
        else:
            components = remaining.split('/')

        for component in components:
            # Skip empty components and '.'
            if component == '' or component == '.':
                continue

            # Handle '..'
            if component == '..':
                # Move to parent (but '/' stays '/')
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                continue

            # Append the component to current path
            if current == '/':
                candidate = '/' + component
            else:
                candidate = current + '/' + component

            # Check if this is a symlink
            if candidate in links:
                # Follow the symlink
                link_count += 1
                if link_count > MAX_LINKS:
                    return None

                target = links[candidate]

                # Resolve remaining components relative to link target
                if target.startswith('/'):
                    # Absolute symlink target
                    current = '/'
                    remaining = target[1:]
                else:
                    # Relative symlink target - relative to the directory containing the link
                    current = candidate.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                    remaining = target

                # Break to reprocess with new current and remaining
                break
            else:
                # Not a symlink, just move to this path
                current = candidate
        else:
            # We've processed all components without hitting a symlink
            break

    # Return the result, removing trailing slash except for '/'
    if current == '/':
        return '/'
    else:
        return current.rstrip('/')

